            loadYamlFromScriptTag(){const scriptElement=document.getElementById(this.dataSourceId);if(!scriptElement)throw new Error('YAML data source not found');this.rawYamlContent=scriptElement.textContent.trim();if(!this.rawYamlContent)throw new Error("YAML content is empty");try{this.yamlData=jsyaml.load(this.rawYamlContent)}catch(e){throw new Error(`YAML parsing error: ${e.message}`)}if(!this.yamlData||Object.keys(this.yamlData).length===0)throw new Error("YAML data is empty or invalid")}
