            findRootNode(){const rootNodeNames=Object.keys(this.yamlData);if(rootNodeNames.length===0)throw new Error("No root node found in YAML");this.rootNode=rootNodeNames[0];this.elements.statusBarTitle.textContent=this.formatNodeName(this.rootNode)}
