            renderHeaderInfo(rootData){const dateTimeField=this.findFieldByKeywords(rootData,["啥时候","时间"]);const locationField=this.findFieldByKeywords(rootData,["俺在哪","地点"]);if(dateTimeField){this.elements.timeDisplay.textContent=rootData[dateTimeField].replace(/[^\p{L}\p{N}\s:年日月]/gu,"");this.elements.timeDisplay.parentNode.querySelector(".emoji").textContent=this.getEmojiForField(dateTimeField)}else{this.elements.timeDisplay.textContent="时间忘了"}if(locationField){this.elements.locationDisplay.textContent=rootData[locationField].replace(/[^\p{L}\p{N}\s:]/gu,"");this.elements.locationDisplay.parentNode.querySelector(".emoji").textContent=this.getEmojiForField(locationField)}else{this.elements.locationDisplay.textContent="地方忘了"}}
            findFieldByKeywords(data,keywords){if(!data||typeof data!=="object")return null;const fields=Object.keys(data);for(const field of fields){for(const keyword of keywords){if(field.toLowerCase().includes(keyword.toLowerCase()))return field}}return null}
            renderCharacters(rootData){const userListField=this.findFieldByKeywords(rootData,["在场的","用户列表"]);const userList=userListField&&Array.isArray(rootData[userListField])?rootData[userListField]:[];this.elements.charactersContainer.innerHTML="";if(userList.length===0){this.elements.charactersContainer.innerHTML=this.createEmptyState("没看见人");return}userList.forEach(userItem=>{if(typeof userItem!=="object"||userItem===null)return;const userTypeKey=Object.keys(userItem)[0];const userData=userItem[userTypeKey];const characterCard=this.createCharacterCard(userData,userTypeKey);if(characterCard)this.elements.charactersContainer.appendChild(characterCard)})}
            createCharacterCard(userData,userType){if(!userData||typeof userData!=="object")return null;const card=document.createElement("div");card.className="rounded-xl p-3.5 shadow-sm card-hover character-card theme-transition";const nameField=this.findFieldByKeywords(userData,["俺是","它是谁","名字"]);let userName=nameField?userData[nameField]:"一个啥玩意";const nameEmojis=this.extractEmojis(userName);const cleanName=userName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu,"").trim();const title=document.createElement("h3");title.className="font-bold text-lg mb-2 pb-1 theme-transition";title.innerHTML=`${nameEmojis[0]||""} ${cleanName}`;card.appendChild(title);const attributesList=document.createElement("ul");attributesList.className="space-y-2 text-sm";card.appendChild(attributesList);Object.keys(userData).forEach(key=>{if(key===nameField)return;const attributeItem=this.createAttributeItem(key,userData[key]);if(attributeItem)attributesList.appendChild(attributeItem)});return card}
