            renderActionOptions(rootData){const actionOptionsField=this.findFieldByKeywords(rootData,["俺想干","行动选项"]);const actionOptions=actionOptionsField&&typeof rootData[actionOptionsField]==="object"?rootData[actionOptionsField]:{};const ownerField=this.findFieldByKeywords(actionOptions,["俺是","名字"]);let ownerName=ownerField?actionOptions[ownerField]:"俺";const ownerEmojis=this.extractEmojis(ownerName);const cleanOwnerName=ownerName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu,"").trim();this.elements.actionOwner.innerHTML=`${ownerEmojis[0]||""} ${cleanOwnerName}`;const optionsField=this.findFieldByKeywords(actionOptions,["选项"]);const options=optionsField&&Array.isArray(actionOptions[optionsField])?actionOptions[optionsField]:[];this.elements.optionsList.innerHTML="";if(options.length===0){this.elements.optionsList.innerHTML=this.createEmptyState("脑子空空");return}options.forEach(optionText=>{const optionEmojis=this.extractEmojis(optionText);const cleanOptionText=optionText.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu,"").trim();const optionItem=document.createElement("li");optionItem.className="pl-2 py-1 border-l-2 ml-1 hover:border-primary/70 transition-colors text-gray-300 theme-transition";optionItem.innerHTML=`${optionEmojis[0]||"▶"} ${cleanOptionText}`;this.elements.optionsList.appendChild(optionItem)})}
